from auto_config.generator.gnb.managed_objects.managed_object import ManagedObject


class TopParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):

        if self.is_mo_ecpri:
            self.set_parameter('topDomainNumber', 24)

        self.set_sPlaneIpAddressDN()

    def set_sPlaneIpAddressDN(self):
        if not self.is_mo_ecpri:
            enb_id = self.enb_ent_config['id']
            if self.enb_ent_config['is_ipv6_splane']:
                self.set_parameter('sPlaneIpAddressDN', f'MRBTS-{enb_id}/TNLSVC-1/TNL-1/IPNO-1/IPIF-1/IPADDRESSV6-1')
            else:
                self.set_parameter('sPlaneIpAddressDN', f'MRBTS-{enb_id}/TNLSVC-1/TNL-1/IPNO-1/IPIF-1/IPADDRESSV4-1')
